import { LogicWrapper, MakeLogicType, afterMount, kea, key, path, props } from 'kea'
import posthog from 'posthog-js'

export interface SourceAlertsLogicProps {
    sourceId?: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface sourceAlertsLogicMeta {
    key: string
}

export type sourceAlertsLogicType = MakeLogicType<{}, {}, SourceAlertsLogicProps, sourceAlertsLogicMeta>

export const sourceAlertsLogic: LogicWrapper<sourceAlertsLogicType> = kea<sourceAlertsLogicType>([
    props({} as SourceAlertsLogicProps),
    key((props) => props.sourceId ?? 'project'),
    path((key) => ['products', 'dataWarehouse', 'sourceAlerts', 'sourceAlertsLogic', key]),
    afterMount(({ props }) => {
        posthog.capture('data_warehouse_alerts_viewed', {
            surface: props.sourceId ? 'source_tab' : 'sources_page',
        })
    }),
])
